#include <cmath>

class Solution {
public:
    int minMoves(int targetX, int targetY) {
        long long s = std::abs((long long)targetX) + std::abs((long long)targetY);
        if (s == 0) return 0;
        long long n = 0;
        long long total = 0;
        while (total < s || (total - s) % 2 != 0) {
            n++;
            total += n;
        }
        return n;
    }
};

class Solution {
    public int minMoves(int targetX, int targetY) {
        long s = Math.abs((long) targetX) + Math.abs((long) targetY);
        if (s == 0) return 0;
        long n = 0;
        long total = 0;
        while (total < s || (total - s) % 2 != 0) {
            n++;
            total += n;
        }
        return (int) n;
    }
}

/**
 * @param {number} targetX
 * @param {number} targetY
 * @return {number}
 */
var minMoves = function(targetX, targetY) {
    const s = Math.abs(targetX) + Math.abs(targetY);
    if (s === 0) return 0;
    let n = 0;
    let total = 0;
    while (total < s || (total - s) % 2 !== 0) {
        n++;
        total += n;
    }
    return n;
};
